// Extraer contenido y adjuntos del mensaje Telegram
const message = $input.body.message;

let content = {
  source: 'telegram',
  chat_id: message.chat.id,
  user_id: message.from.id,
  text: message.text || '',
  has_photo: !!message.photo,
  has_document: !!message.document,
  timestamp: new Date(message.date * 1000).toISOString(),
  trace_id: 'tg-' + message.message_id
};

// Si tiene foto, extraer URL
if (message.photo) {
  const photo = message.photo[message.photo.length - 1];
  content.image_file_id = photo.file_id;
}

// Si tiene documento (PDF, etc)
if (message.document) {
  content.document_file_id = message.document.file_id;
  content.document_name = message.document.file_name;
}

return content;

// Procesar archivos adjuntos si existen
// Nota: En producción, descargar archivos y procesar con OCR/servicios

const content = $input.body;

if (content.image_file_id) {
  // Placeholder: Enviar a servicio OCR
  content.processing_hint = 'image_ocr_required';
}

if (content.document_file_id) {
  // Placeholder: Enviar a servicio PDF extraction
  content.processing_hint = 'pdf_extraction_required';
}

return content;

// Responder en el mismo canal (Telegram)
const response = $input.body.response;
const chat_id = $input.body.chat_id;

return {
  text: response || 'Procesando tu solicitud...',
  chat_id: chat_id,
  parse_mode: 'HTML'
};
